import re

from moler.exceptions import CommandFailure, CommandTimeout, ParsingDone

from ta_moler.cmd.rtg.uesimdump.genericrtg_uesimdump import GenericRtgUeSimDump
from ta_moler.helpers.parsers.asn_parser import AsnParser
from ta_moler.helpers.parsers.nas_parser import NasParser


class Dump(GenericRtgUeSimDump):
    """Dump command class."""

    # ...
    _re_prompt_nas = re.compile(r"^(\.\.\.)")
    # }
    _re_prompt_rrc = re.compile(r"^\}")

    def __init__(self, connection, message_to_parse, prompt=None, newline_chars=None, runner=None):
        """
        Dump command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param message_to_parse: Message to be parsed.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        """
        super(Dump, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.message_to_parse = message_to_parse
        self.full_message = ""
        self.full_message_unchanged = ""
        self._end_added = False
        self.timeout = 1
        self.terminating_timeout = 0.0

        self.nas = ""
        self.rrc = ""

    def _detect_start_of_cmd_output(self, line, is_full_line):
        """
        Detect if command started.

        :param line: line to check if echo of command is sent by device
        :return: None
        """
        self._cmd_escaped = re.escape(str(self.command_string)[0:50])
        if is_full_line and self._regex_helper.search(self._cmd_escaped, line):
            self._cmd_output_started = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = self.message_to_parse

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            self.full_message += line
            self.full_message += "\n"
            self.full_message_unchanged += line.rstrip()
            self.full_message_unchanged += "\n"
            try:
                self._parse_error(line)
                self._find_nas()
                self._find_rrc()
            except ParsingDone:
                pass
        return super(Dump, self).on_new_line(line, is_full_line)

    # ---
    # MessageType: attachAccept
    # NAS:
    #   Unit: 0.1_h
    #   Value: 31
    # ...
    _re_nas = re.compile(r"^---(?P<NAS>[.\s*\w\W]*)\.\.\.")

    def _find_nas(self):
        """
        Find nas pattern.

        :return:    None
        """
        match = re.search(Dump._re_nas, self.full_message)
        if match and not self.nas:
            self.nas = match.group("NAS")
            self.full_message = self.full_message.replace(self.nas, "")
            self._parse_nas()
            raise ParsingDone

    def _parse_nas(self):
        """
        Parse found nas message into dict format.

        :return:    None
        """
        if self.nas:
            self.nas = NasParser.parse(self.nas)

    # value CtrlToWsMessage ::=
    # {
    #   message c1 : rrcConnectionSetupComplete :
    #    {
    #      rrc-TransactionIdentifier 2
    #    }
    # }
    _re_rrc = re.compile(r"(?P<RRC>value[.\s\w\W]*\n\})")

    def _find_rrc(self):
        """
        Find rrc pattern.

        :return:    None
        """
        match = re.search(Dump._re_rrc, self.full_message)
        if match and not self.rrc:
            self.rrc = match.group("RRC")
            self.full_message = self.full_message.replace(self.rrc, "")
            self._parse_rrc()
            raise ParsingDone

    def _parse_rrc(self):
        """
        Parse found nas message into dict format.

        :return:    None
        """
        if self.rrc:
            rrc = self.rrc.split("\n")
            rrc.pop(0)
            self.rrc = "\n".join(rrc)
            self.rrc = AsnParser.parse(self.rrc)

    # terminate called after throwing an instance of 'std::regex_error'
    _re_error = re.compile(r"(?P<ERROR>terminate called[.\s\w\W]*)")

    def _parse_error(self, line):
        """
        Stop command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Dump._re_error, line):
            self.current_ret["ERROR"] = self._regex_helper.group("ERROR")
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))

            raise ParsingDone

    def set_exception(self, exception):
        """
        Use to indicate some failure during observation.

        :param exception: Exception to set.
        :return: None
        """
        if type(exception) is CommandTimeout and len(self.current_ret) == 0:
            self._is_done = False
            self.current_ret["input"] = self.message_to_parse
            self.current_ret["raw"] = self.full_message_unchanged
            self.current_ret["rrc"] = self.rrc
            self.current_ret["nas"] = self.nas
            self.set_result(self.current_ret)
        else:
            self.current_ret["input"] = self.message_to_parse
            self.current_ret["raw"] = self.full_message_unchanged
            self.current_ret["rrc"] = self.rrc
            self.current_ret["nas"] = self.nas
            super(Dump, self).set_exception(exception)

    def is_end_of_cmd_output(self, line):
        """
        Check if given line is recognized as command end.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :return: Bool
        """
        if "::=" in self.full_message or "::=" in self.full_message_unchanged:
            if self._regex_helper.search_compiled(Dump._re_prompt_rrc, line):
                return True
        else:
            if self._regex_helper.search_compiled(Dump._re_prompt_nas, line):
                return True
        return False

    def on_timeout(self):
        """
        Call callback by framework when timeout occurs.

        :return: None
        """


